public sealed class BankAccount(decimal openingBalance)
{
    public decimal Balance { get; private set; } = openingBalance >= 0
        ? openingBalance : throw new ArgumentOutOfRangeException(nameof(openingBalance));

    public void Withdraw(decimal amount)
    {
        if (amount <= 0 || amount > Balance)
            throw new InvalidOperationException("Invalid withdrawal.");

        Balance -= amount;
    }
}

