public sealed record Sale(string Region, decimal Amount, bool Paid);
public sealed record RegionTotal(string Region, decimal Revenue);

public static List<RegionTotal> Summarize(IEnumerable<Sale> sales)
{
    return sales.Where(sale => sale.Paid)
        .GroupBy(sale => sale.Region)
        .Select(group => new RegionTotal(
            group.Key, group.Sum(sale => sale.Amount)))
        .OrderByDescending(total => total.Revenue)
        .ToList();
}

