public sealed record ShippingQuote(decimal Cost, string Service);

public static ShippingQuote Quote(decimal weight, string? region)
{
    ArgumentOutOfRangeException.ThrowIfNegativeOrZero(weight);
    ArgumentException.ThrowIfNullOrWhiteSpace(region);

    return (weight, region) switch
    {
        (<= 1m, "Local") => new(3m, "Standard"),
        (<= 5m, "Local") => new(7m, "Standard"),
        _ => new(15m, "Tracked")
    };
}
